"""
CVE and CWE Enterprise Vulnerability Database and Scoring Engine.
Provides comprehensive vulnerability records, CVSS v3.1 mathematical scoring,
CWE weakness taxonomy, affected CPE trees, and automated remediation guidance.
"""

from __future__ import annotations
from dataclasses import dataclass, field
from enum import Enum
from typing import Dict, List, Optional, Any
import math


class Severity(str, Enum):
    NONE = "NONE"
    LOW = "LOW"
    MEDIUM = "MEDIUM"
    HIGH = "HIGH"
    CRITICAL = "CRITICAL"


@dataclass(frozen=True)
class CweWeakness:
    cwe_id: str
    name: str
    description: str
    typical_severity: Severity
    url: str = ""

    def __post_init__(self):
        if not self.url:
            num = self.cwe_id.replace("CWE-", "")
            object.__setattr__(self, 'url', f"https://cwe.mitre.org/data/definitions/{num}.html")


@dataclass
class CveVulnerability:
    cve_id: str
    title: str
    description: str
    cvss_v31_vector: str
    base_score: float
    severity: Severity
    cwe_id: str
    affected_cpes: List[str]
    is_known_exploited: bool
    ransomware_campaign_associated: bool
    epss_score: float
    remediation_guidance: str
    references: List[str] = field(default_factory=list)

    def __post_init__(self):
        if not self.references:
            self.references = [
                f"https://nvd.nist.gov/vuln/detail/{self.cve_id}",
                f"https://cve.mitre.org/cgi-bin/cvename.cgi?name={self.cve_id}"
            ]


