class CvssV31Calculator:
    """
    Complete implementation of the FIRST Common Vulnerability Scoring System (CVSS) v3.1 specification.
    Calculates Base Score, Exploitability Sub-score, and Impact Sub-score from vector string.
    """

    AV_MAP = {"N": 0.85, "A": 0.62, "L": 0.55, "P": 0.2}
    AC_MAP = {"L": 0.77, "H": 0.44}
    PR_MAP_UNCHANGED = {"N": 0.85, "L": 0.62, "H": 0.27}
    PR_MAP_CHANGED = {"N": 0.85, "L": 0.68, "H": 0.5}
    UI_MAP = {"N": 0.85, "R": 0.62}
    CIA_MAP = {"N": 0.0, "L": 0.22, "H": 0.56}

    @classmethod
    def roundup(cls, val: float) -> float:
        return math.ceil(val * 10) / 10.0

    @classmethod
    def calculate_from_vector(cls, vector_str: str) -> Dict[str, Any]:
        parts = {}
        for token in vector_str.replace("CVSS:3.1/", "").split("/"):
            if ":" in token:
                k, v = token.split(":", 1)
                parts[k] = v

        av = parts.get("AV", "N")
        ac = parts.get("AC", "L")
        pr = parts.get("PR", "N")
        ui = parts.get("UI", "N")
        scope = parts.get("S", "U")
        c = parts.get("C", "N")
        i = parts.get("I", "N")
        a = parts.get("A", "N")

        av_val = cls.AV_MAP.get(av, 0.85)
        ac_val = cls.AC_MAP.get(ac, 0.77)
        ui_val = cls.UI_MAP.get(ui, 0.85)

        if scope == "C":
            pr_val = cls.PR_MAP_CHANGED.get(pr, 0.85)
        else:
            pr_val = cls.PR_MAP_UNCHANGED.get(pr, 0.85)

        c_val = cls.CIA_MAP.get(c, 0.0)
        i_val = cls.CIA_MAP.get(i, 0.0)
        a_val = cls.CIA_MAP.get(a, 0.0)

        iss = 1.0 - ((1.0 - c_val) * (1.0 - i_val) * (1.0 - a_val))

        if scope == "U":
            impact = 6.42 * iss
        else:
            impact = 7.52 * (iss - 0.029) - 3.25 * ((iss - 0.02) ** 15)

        exploitability = 8.22 * av_val * ac_val * pr_val * ui_val

        if impact <= 0:
            base_score = 0.0
        else:
            if scope == "U":
                base_score = cls.roundup(min(impact + exploitability, 10.0))
            else:
                base_score = cls.roundup(min(1.08 * (impact + exploitability), 10.0))

        if base_score == 0.0:
            severity = Severity.NONE
        elif base_score <= 3.9:
            severity = Severity.LOW
        elif base_score <= 6.9:
            severity = Severity.MEDIUM
        elif base_score <= 8.9:
            severity = Severity.HIGH
        else:
            severity = Severity.CRITICAL

        return {
            "vector": vector_str,
            "base_score": base_score,
            "severity": severity,
            "impact_subscore": round(impact, 2),
            "exploitability_subscore": round(exploitability, 2),
            "scope": scope
        }


class CveDatabaseEngine:
    """Query and management engine for CVE vulnerabilities and CWE taxonomy."""

    @classmethod
    def get_cve(cls, cve_id: str) -> Optional[CveVulnerability]:
        return CVE_CATALOG.get(cve_id)

    @classmethod
    def get_cwe(cls, cwe_id: str) -> Optional[CweWeakness]:
        return CWE_CATALOG.get(cwe_id)

    @classmethod
    def get_by_severity(cls, severity: Severity) -> List[CveVulnerability]:
        return [c for c in CVE_CATALOG.values() if c.severity == severity]

    @classmethod
    def get_known_exploited_vulnerabilities(cls) -> List[CveVulnerability]:
        return [c for c in CVE_CATALOG.values() if c.is_known_exploited]

    @classmethod
    def get_ransomware_associated_vulnerabilities(cls) -> List[CveVulnerability]:
        return [c for c in CVE_CATALOG.values() if c.ransomware_campaign_associated]

    @classmethod
    def search_by_cpe(cls, cpe_substring: str) -> List[CveVulnerability]:
        cpe_sub = cpe_substring.lower()
        return [
            c for c in CVE_CATALOG.values()
            if any(cpe_sub in cpe.lower() for cpe in c.affected_cpes)
        ]

    @classmethod
    def search(cls, query: str) -> List[CveVulnerability]:
        q = query.lower()
        return [
            c for c in CVE_CATALOG.values()
            if q in c.cve_id.lower() or q in c.title.lower() or q in c.description.lower()
        ]

    @classmethod
    def get_database_summary(cls) -> Dict[str, Any]:
        total = len(CVE_CATALOG)
        critical = sum(1 for c in CVE_CATALOG.values() if c.severity == Severity.CRITICAL)
        high = sum(1 for c in CVE_CATALOG.values() if c.severity == Severity.HIGH)
        medium = sum(1 for c in CVE_CATALOG.values() if c.severity == Severity.MEDIUM)
        kev = sum(1 for c in CVE_CATALOG.values() if c.is_known_exploited)
        ransomware = sum(1 for c in CVE_CATALOG.values() if c.ransomware_campaign_associated)

        return {
            "total_cves": total,
            "total_cwes": len(CWE_CATALOG),
            "critical_count": critical,
            "high_count": high,
            "medium_count": medium,
            "cisa_kev_count": kev,
            "ransomware_associated_count": ransomware,
            "average_base_score": round(sum(c.base_score for c in CVE_CATALOG.values()) / total, 2) if total else 0.0
        }
